using SobhanNotificationHub.Services;using SobhanNotificationHub.UI;namespace SobhanNotificationHub;public partial class MainWindow:System.Windows.Window{public MainWindow(){InitializeComponent();Refresh();}private void Refresh(){var c=App.Services.CurrentConfig;StatusText.Text=App.Services.TokenStore.HasCredentials?"متصل به سامانه سبحان":"اتصال برقرار نیست";UserText.Text=c is null?"":$"{c.User.DisplayName} · {c.User.Unit} · {c.User.Role}";}private async void Check_Click(object s,RoutedEventArgs e){await PollingWorker.PollOnceAsync(App.Services,CancellationToken.None);StatusText.Text="بررسی انجام شد";}private void History_Click(object s,RoutedEventArgs e)=>new NotificationHistoryWindow().Show();private void Settings_Click(object s,RoutedEventArgs e)=>new SettingsWindow().Show();private void Hide_Click(object s,RoutedEventArgs e)=>Hide();protected override void OnClosing(System.ComponentModel.CancelEventArgs e){e.Cancel=true;Hide();}}
